def chromatic_number(edges):
    n = 9
    # Build adjacency
    adj = [[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Try k=2,3,4
    for k in range(2, 5):
        # Backtracking search for k-coloring
        colors = [-1]*n
        def backtrack(v):
            if v == n:
                return True
            used = set()
            for nb in adj[v]:
                if colors[nb] != -1:
                    used.add(colors[nb])
            for c in range(k):
                if c not in used:
                    colors[v] = c
                    if backtrack(v+1):
                        return True
                    colors[v] = -1
            return False
        if backtrack(0):
            return k
    return None

